import {createHarness} from '../../src/harness.mjs';import {Effect} from 'effect';const run=Effect.runPromise;const h=createHarness({directory:process.argv[2],runner:async()=>{process.stdout.write('ATTEMPT_STARTED\n');process.stdin.resume();return new Promise(()=>{});}});let t=await run(h.create('alice','Reminder due exactly now'));t=await run(h.command('alice',t.id,{id:'confirm',version:t.version,type:'confirm',inclusive:true,excludeCompleted:true}));t=await run(h.command('alice',t.id,{id:'approve',version:t.version,type:'approve',digest:t.plan.digest}));process.stdout.write('TASK '+t.id+'\n');await run(h.runNext(t.id));
